<?php
namespace App\Domain\Solutions;
use App\Domain\PublicChrome\PublicAssetPath; use App\Models\{Solution,SolutionCategory}; use Illuminate\Support\Facades\Cache; use Throwable;
final class SolutionIndexViewData { public function get(?string $category,int $page):array{try{return Cache::remember('public.solutions.index.v1.'.SolutionCache::indexVersion().'.'.($category?:'all').'.'.$page,now()->addMinutes(10),fn()=>$this->load($category,$page));}catch(Throwable){return $this->load($category,$page);}} private function load(?string $category,int $page):array{$categoryModel=$category?SolutionCategory::where('slug',$category)->where('is_active',true)->first():null;if($category&&!$categoryModel)return ['invalid'=>true,'items'=>[],'categories'=>[],'pagination'=>[]];$p=Solution::publiclyVisible()->with('category')->when($categoryModel,fn($q)=>$q->whereBelongsTo($categoryModel))->orderByDesc('is_featured')->orderBy('display_order')->paginate(12,['*'],'page',$page);return ['invalid'=>false,'categories'=>SolutionCategory::where('is_active',true)->orderBy('display_order')->limit(50)->get()->map(fn($c)=>['name'=>$c->name,'slug'=>$c->slug])->all(),'items'=>$p->getCollection()->map(fn($s)=>['title'=>$s->title,'slug'=>$s->slug,'description'=>$s->short_description,'featured'=>(bool)$s->is_featured,'image'=>PublicAssetPath::isSafe($s->featured_image_path)?$s->featured_image_path:null,'image_alt'=>$s->featured_image_alt,'category'=>$s->category?->name,'url'=>route('solutions.show',$s->slug)])->all(),'pagination'=>['current'=>$p->currentPage(),'last'=>$p->lastPage(),'previous'=>$p->previousPageUrl(),'next'=>$p->nextPageUrl(),'total'=>$p->total()]];} }
